const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  var palmSprings = ee.Geometry.Point([-116.5453, 33.8303]);
  var startDate = '2017-06-15';
  var endDate = '2017-06-22'; // exclusive, so includes 21st

  // 2. Data Acquisition & Check
  var collection = ee.ImageCollection('ECMWF/ERA5_LAND/HOURLY')
    .filterDate(startDate, endDate)
    .filterBounds(palmSprings)
    .select('temperature_2m'); // in Kelvin

  var count = collection.size().getInfo();
  if (count === 0) {
    console.log('No temperature data found for the given period.');
    console.log('<answer>C1</answer>');
    return;
  }
  console.log('Hourly images: ' + count);

  // 3. Processing: Get maximum temperature over the period
  var maxTempImage = collection.max();
  var tempResult = maxTempImage.reduceRegion({
    reducer: ee.Reducer.first(),
    geometry: palmSprings,
    scale: 1000,
    maxPixels: 1e9
  }).get('temperature_2m');

  var tempK = tempResult.getInfo();
  if (tempK === null) {
    console.log('No valid temperature pixel at location.');
    console.log('<answer>C2</answer>');
    return;
  }

  // 4. Calculation: Convert Kelvin to Fahrenheit
  var tempC = tempK - 273.15;
  var tempF = tempC * 9/5 + 32;
  console.log('Max temperature (F): ' + tempF.toFixed(2));

  // 5. Validation & Final Answer
  if (tempF === null || isNaN(tempF)) {
    console.log('<answer>C3</answer>');
  } else if (tempF >= 115) {
    console.log('<answer>A</answer>');
  } else {
    console.log('<answer>B</answer>');
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
